import { tinker } from "@tinker/start/vite";
import { defineConfig } from "vite-plus";

export default defineConfig({
  plugins: [
    tinker({
      serverEntry: "cmds/server.ts",
      routerEntry: "cmds/router.ts",
      startEntry: "cmds/start.ts",
    }),
  ],
});

import { createScope } from "@tinker/core";

import { defineMain, checkClosed } from "~/base/main";
import { renderObservation } from "~/base/observe";
import { observeServerPanics } from "~/base/panics.server";
import { createServerHandler, stoppedFetch } from "~/base/server-entry";
import { abortReasons } from "~/components/errors";
import { startRequests, backendStop } from "~/components/requests";
import {
  telemetryExport,
  telemetrySide,
  telemetryService,
  tracesUrl,
  logsUrl,
  logLevel,
  spanHistory,
  consoleOutput,
  observer,
  renderObserve,
  renderNs,
  browserIngest,
  browserTelemetry,
} from "~/components/telemetry/index.server";

/** The host starts the server; importing this command opens nothing. */
// oxlint-disable-next-line complexity -- Commands keep env bindings inline. Tests cover input, startup, exit, and close.
export default defineMain(async ({ env, args, signal, stdout, stderr, exit }) => {
  if (args.length) {
    stderr.write("Usage: tinker serve\n");
    exit(64);
    return { fetch: stoppedFetch, closed: Promise.resolve() };
  }
  try {
    const stop = { tools: new AbortController(), app: new AbortController() };
    const appStop = AbortSignal.any([signal, stop.app.signal]);
    const tools = createScope({
      signal: stop.tools.signal,
      extensions: [telemetryExport],
      tags: [
        telemetrySide("server"),
        consoleOutput(stdout),
        env.OTEL_SERVICE_NAME !== undefined && telemetryService(env.OTEL_SERVICE_NAME),
        env.VICTORIA_TRACES_URL !== undefined && tracesUrl(new URL(env.VICTORIA_TRACES_URL)),
        env.VICTORIA_LOGS_URL !== undefined && logsUrl(new URL(env.VICTORIA_LOGS_URL)),
        env.LOG_LEVEL !== undefined && logLevel(Number(env.LOG_LEVEL)),
        env.SPAN_HISTORY !== undefined && spanHistory(Number(env.SPAN_HISTORY)),
      ],
    });

    await tools.ready;

    try {
      const app = createScope({
        signal: appStop,
        observe: tools.resolve(observer),
        extensions: [startRequests],
        tags: [
          backendStop(appStop),
          renderObservation(tools.resolve(renderObserve, { ns: renderNs })),
          browserTelemetry(tools.resolve(browserIngest).ingest),
        ],
      });

      let serving = false;

      const closed = app.closed
        .then(async function closeRoots(appEnd) {
          stop.tools.abort(abortReasons.closed);
          const toolsEnd = await tools.closed;

          checkClosed(appEnd);

          checkClosed(toolsEnd);
        })
        .catch((error) => {
          if (!serving) throw error;
          exit(1, error);
        });
      void closed.catch(() => {});

      try {
        await app.ready;
        signal.throwIfAborted(); // Aborted during start: app is closing, so no handler.
        serving = true;
      } catch (error) {
        await closed.catch((cleanup) => {
          if (cleanup !== error) stderr.write(`close failed: ${String(cleanup)}\n`);
        });
        throw error;
      }
      app.onClose(observeServerPanics(exit.bind(null, 1), closed, stderr));
      return {
        fetch: createServerHandler(
          { requestContext: app.resolve(startRequests) },
          { dev: import.meta.env.DEV },
        ).fetch,
        closed,
      };
    } catch (error) {
      stop.tools.abort(error);
      try {
        checkClosed(await tools.closed);
      } catch (cleanup) {
        if (cleanup !== error) stderr.write(`close failed: ${String(cleanup)}\n`);
      }
      throw error;
    }
  } catch (error) {
    let code = 1;
    if (error && typeof error === "object") {
      if ("kind" in error && ["MissingTag", "DataValidationFailed"].includes(String(error.kind))) {
        code = 78;
      }
      if ("code" in error && error.code === "ERR_INVALID_URL") code = 78;
    }
    exit(code, error);
    return { fetch: stoppedFetch, closed: Promise.resolve() };
  }
});

import { createScope } from "@tinker/core";

import {
  createRouterEntry,
  pageEvents,
  readRenderObservation,
  routerScope,
  tabLifetime,
} from "~/base/router-entry";
import { abortReasons } from "~/components/errors";
import {
  telemetryExport,
  telemetrySide,
  telemetryService,
  logConsole,
  observer,
} from "~/components/telemetry";

/** Start asks for a fresh render root; the browser keeps its root until page hide. */
export async function getRouter() {
  const stop = { tools: new AbortController(), app: new AbortController() };
  const tools = import.meta.env.SSR
    ? undefined
    : createScope({
        signal: stop.tools.signal,
        extensions: [telemetryExport],
        tags: [telemetrySide("browser"), telemetryService("tinker-browser"), logConsole(console)],
      });

  try {
    await tools?.ready;
    const app = createScope({
      signal: stop.app.signal,
      extensions: [routerScope],
      observe: tools ? tools.resolve(observer) : readRenderObservation(),
      tags: [pageEvents(import.meta.env.SSR ? undefined : window)],
    });
    const closed = app.closed.then(async (appEnd) => {
      stop.tools.abort(abortReasons.closed);
      const toolsEnd = await tools?.closed;

      for (const result of [appEnd, toolsEnd]) {
        if (result?.status === "failed") throw result.error;
        if (result?.teardownErrors?.length) throw result.teardownErrors[0];
      }
    });
    void closed.catch(() => {});
    const close = () => {
      stop.app.abort(abortReasons.closed);
      return closed;
    };

    return await app.ready
      .then(async () => {
        app.resolve(tabLifetime).bind(close);
        if (import.meta.hot) import.meta.hot.dispose(close);
        return createRouterEntry({
          options: { context: {} },
          Wrap: app.resolve(routerScope),
          close,
          dev: import.meta.env.DEV,
          server: import.meta.env.SSR,
        });
      })
      .catch(async (error) => {
        await close().catch((cleanup) => {
          if (cleanup !== error) console.error(cleanup);
        });
        throw error;
      });
  } catch (error) {
    stop.tools.abort(abortReasons.closed);
    await tools?.closed;
    throw error;
  }
}

import { operation } from "@tinker/core";
import { z } from "zod";

export const greet = operation({
  label: "greet",
  input: z.object({ name: z.string().min(1) }),
  run: (_deps, { input }) => ({ text: `Hello, ${input.name}.` }),
});

import { createServerFn } from "@tanstack/react-start";

import { startRequests } from "~/components/requests";
import { readResult } from "~/components/requests/index.server";

import { greet } from "@/backend/greet";

export const runGreet = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) =>
    readResult(
      await context.session.settle(greet, {
        input: { name: "world" },
        signal: context.signal,
      }),
    ),
  );

import { createFileRoute } from "@tanstack/react-router";

import { runGreet } from "@/transport/greet.functions";

export const Route = createFileRoute("/")({
  loader: () => runGreet(),
  component: () => <p>{Route.useLoaderData().text}</p>,
});

import { createStartEntry } from "~/base/start-entry";
import { startRequests } from "~/components/requests";

import { startInstance as app } from "@/start";

export const startInstance = createStartEntry(async (csrf) => {
  const own = await app.getOptions();
  return {
    ...own,
    requestMiddleware: [csrf, startRequests.middleware, ...(own.requestMiddleware ?? [])],
  };
});

import { createStart } from "@tanstack/react-start";

/** The command reads this app-owned Start setup; keep it even when options are empty. */
export const startInstance = createStart(() => ({}));

import { createRootRoute, HeadContent, Outlet, Scripts } from "@tanstack/react-router";

import style from "@/style.css?url";

/** The app owns its page shell and stylesheet. */
export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { title: "Tinker app" },
    ],
    links: [{ rel: "stylesheet", href: style }],
  }),
  component: () => <Outlet />,
  shellComponent: ({ children }) => (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  ),
});

import { createFileRoute } from "@tanstack/react-router";

import { health } from "~/components/health";
import { startRequests } from "~/components/requests";
import { readResult } from "~/components/requests/index.server";

export const Route = createFileRoute("/api/health")({
  server: {
    middleware: [startRequests.middleware],
    handlers: {
      GET: async ({ context }) =>
        Response.json(
          readResult(await context.session.settle(health, { signal: context.signal })),
          {
            headers: { "Cache-Control": "no-store" },
          },
        ),
    },
  },
});

import { createFileRoute } from "@tanstack/react-router";

import { startRequests } from "~/components/requests";
import { readResult } from "~/components/requests/index.server";
import {
  receiveTelemetry,
  telemetryBody,
  telemetryOrigin,
} from "~/components/telemetry/index.server";

const previewOrigin = /^http:(\/\/[^/:]+\.preview\.tini\.works)$/;

/** The copied route owns HTTP checks and replies; the component owns bounded batch reads. */
export const Route = createFileRoute("/api/telemetry")({
  server: {
    middleware: [startRequests.middleware],
    handlers: {
      POST: async ({ request, context }) => {
        const origin = context.session.resolve(telemetryOrigin);
        const expected =
          origin === null
            ? new URL(request.url).origin.replace(previewOrigin, "https:$1")
            : new URL(origin).origin;
        const refused = [
          [request.headers.get("origin") !== expected, 403],
          [request.headers.get("content-type")?.split(";")[0] !== "application/json", 415],
          [Number(request.headers.get("content-length")) > 65_536, 413],
        ].find(([refused]) => refused);
        if (refused) return new Response(null, { status: Number(refused[1]) });

        const body = request.body;
        if (body === null) return new Response(null, { status: 400 });
        const batch = await context.session.resolve(telemetryBody).read(body);
        if (typeof batch === "number") return new Response(null, { status: batch });

        const result = await context.session.settle(receiveTelemetry, {
          input: batch,
          signal: request.signal,
        });
        if (result.status === "failed" && Object(result.error).kind === "Cancelled") {
          return new Response(null, { status: 503 });
        }
        readResult(result);
        return new Response(null, { status: 202, headers: { "Cache-Control": "no-store" } });
      },
    },
  },
});

